// Screen routing and durable game state.
function showHome(){mode='menu';screen='home';activeMatch=null;document.getElementById('hud').classList.add('hidden');document.getElementById('mainUI').classList.remove('hidden');document.getElementById('home').classList.remove('hidden');document.getElementById('panel').classList.add('hidden');document.getElementById('shade').classList.remove('hidden');document.getElementById('matchresult').classList.add('hidden');updateCoins()}
function showPanel(html){screen='panel';document.getElementById('home').classList.add('hidden');let p=document.getElementById('panel');p.innerHTML=html;p.classList.remove('hidden')}
function backButton(){return '<button class="btn small" data-action="back">← Back</button>'}
function fightersScreen(){showPanel(`<div class="panelhead"><div><div class="eyebrow">Choose your legend</div><h2>Fighter roster</h2><div class="sub">${save.unlockedFighters.length} / 20 available · each legend fights with distinct stats and a signature special.</div></div>${backButton()}</div><div class="grid">${roster.map(f=>{let unlocked=save.unlockedFighters.includes(f.id),active=f.id===selectedFighter;return `<button class="card ${active?'selected':''} ${unlocked?'':'locked'}" data-fighter="${f.id}" style="--accent:${f.accent}"><span class="portrait">${f.emoji}</span><strong>${f.name} ${unlocked?'':'🔒'}</strong><small>${f.gender==='F'?'Female':'Male'} · ${f.style}</small><small>Special: ${f.move}</small><small>ATK ${f.stats[1]} · SPD ${f.stats[3]} · DEF ${f.stats[2]}</small><span class="cost">${unlocked?'SELECTED':`UNLOCK · ${f.unlock?.toLocaleString()||'Championship'}`} LC</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Unlock any legend with earned coins. Four launch fighters are ready to play.</span><button class="btn primary" data-action="fighter-confirm">Choose ${byId(selectedFighter).name}</button></div>`)}
function arenaScreen(){showPanel(`<div class="panelhead"><div><div class="eyebrow">Seven living stages</div><h2>Select arena</h2><div class="sub">Animated environments · ${save.settings.time==='cycle'?'automatic light cycle':save.settings.time+' lighting'}</div></div>${backButton()}</div><div class="grid">${arenas.map((a,i)=>{let ok=save.unlockedArenas.includes(i),active=i===selectedArena;return `<button class="card ${active?'selected':''} ${ok?'':'locked'}" data-arena="${i}" style="--accent:${a.colors[1]}"><span class="portrait">${a.emoji}</span><strong>${a.name} ${ok?'':'🔒'}</strong><small>${a.unlock}</small><small>${['Neon skyline & signage','Lantern-lit wooden hall','Waves, palms & sunset','Steamworks fight pit','Rooftop skyline','Ancient mountain ruins','Roman crowd & banners'][i]}</small><span class="cost">${ok?'AVAILABLE':'LOCKED'}</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Win matches to open new stages. Locked arenas cannot be entered.</span><button class="btn primary" data-action="arena-confirm">Fight here</button></div>`)}
function shopScreen(){let lists={outfits:roster.flatMap(f=>[{id:`${f.id}-street`,fighter:f.id,name:`${f.name} · Street alt`,desc:'Alternate streetwear palette',price:1000,type:'outfit'},{id:`${f.id}-legend`,fighter:f.id,name:`${f.name} · Legend`,desc:'Championship colorway',price:2500,type:'outfit'}]),accessories:[{id:'red-gloves',name:'Crimson gloves',desc:'A bold classic pair',price:500,type:'accessory',emoji:'🥊'},{id:'gold-boots',name:'Gold high-tops',desc:'Step into the spotlight',price:750,type:'accessory',emoji:'👟'},{id:'star-headband',name:'Star headband',desc:'A bright champion band',price:800,type:'accessory',emoji:'⭐'},{id:'shadow-mask',name:'Shadow mask',desc:'Mystery for the main event',price:900,type:'accessory',emoji:'🥷'}],finishers:roster.map(f=>({id:`${f.id}-finisher`,fighter:f.id,name:`${f.name} · Signature Finish`,desc:f.move+' knockout sequence',price:5000,type:'finisher',emoji:f.emoji}))};let items=lists[shopCategory];showPanel(`<div class="panelhead"><div><div class="eyebrow">Earn it. Wear it. Own the streets.</div><h2>Legends Market</h2><div class="sub">Balance: <b class="coin">${save.coins.toLocaleString()} LC</b> · no duplicates · purchases saved locally</div></div>${backButton()}</div><div class="category">${[['outfits','Outfits'],['accessories','Accessories'],['finishers','Finishers']].map(([id,l])=>`<button class="btn small ${shopCategory===id?'primary':''}" data-category="${id}">${l}</button>`).join('')}</div><div class="grid">${items.map(it=>{let owned=save.owned.includes(it.id),equipped=save.equipped[it.fighter]===it.id;return `<button class="card ${selectedItem===it.id?'selected':''}" data-item="${it.id}" style="--accent:${it.fighter?byId(it.fighter).accent:'#ba8f56'}"><span class="portrait">${it.emoji||'✦'}</span><strong>${it.name}</strong><small>${it.desc}</small><span class="cost">${owned?(equipped?'EQUIPPED · ': 'OWNED · '):`${it.price.toLocaleString()} LC`}</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Select an item, then purchase or equip it. Cosmetics never affect combat balance.</span><button class="btn" data-action="shop-equip">Equip / Unequip</button><button class="btn primary" data-action="shop-buy">Purchase selected</button></div>`)}
