const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find(x => x.url.includes('/index.html'));
if (!target) throw new Error('Street Legends tab not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
let id = 0;
const pending = new Map();
ws.addEventListener('message', event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
function call(method, params={}) { const n=++id; return new Promise(resolve => { pending.set(n,resolve); ws.send(JSON.stringify({id:n,method,params})); }); }
async function evaluate(expression) {
  const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});
  if(r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.text);
  return r.result?.result?.value;
}
await call('Page.enable');
await call('Runtime.enable');
console.log('page', await evaluate('document.title'), 'ready', await evaluate('document.readyState'));
console.log('menu before', await evaluate('({mode,selectedFighter,roster:roster.length})'));
await evaluate("document.querySelector('[data-action=play]').click()");
await new Promise(r=>setTimeout(r,1400));
console.log('match', await evaluate("({mode,active:!!activeMatch,difficulty:activeMatch?.difficulty, player:{id:activeMatch?.player.fighter.id,x:activeMatch?.player.x,y:activeMatch?.player.y,pose:activeMatch?.player.pose},enemy:{id:activeMatch?.enemy.fighter.id,x:activeMatch?.enemy.x,hp:activeMatch?.enemy.hp,pose:activeMatch?.enemy.pose},arena:activeMatch?.arena,elapsed})"));
const shot=await call('Page.captureScreenshot',{format:'png'});
await import('node:fs/promises').then(fs=>fs.writeFile('/tmp/opencode/street-gameplay.png',Buffer.from(shot.result.data,'base64')));
console.log('screenshot /tmp/opencode/street-gameplay.png');
console.log('errors', await evaluate('window.__errs||[]'));
ws.close();

