const targets=await(await fetch('http://127.0.0.1:9222/json')).json(),target=targets.find(x=>x.url.includes('/index.html'));
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.addEventListener('open',r,{once:true});ws.addEventListener('error',j,{once:true})});
let id=0;const pending=new Map(),errors=[];ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}});
function call(method,params={}){const n=++id;return new Promise(r=>{pending.set(n,r);ws.send(JSON.stringify({id:n,method,params}))})}
