function drawArena(idx,t=anim){const a=arenas[idx]||arenas[0],d=dayBlend(),w=W,h=H,night=d;let [sky1,sky2,glow]=a.colors;
 let top=sky1,bottom=sky2;if(a.type==='city'||a.type==='roof'){top=hexMix('#5294bb','#10162f',night);bottom=hexMix('#edaa82','#25284d',night)}else if(a.type==='beach'){top=hexMix('#6bb6d0','#292856',night);bottom=hexMix('#ffd18c','#b55071',night)}else if(a.type==='dojo'){top=hexMix('#916b52','#211d2b',night);bottom=hexMix('#ddb37c','#4d3e42',night)}else if(a.type==='temple'){top=hexMix('#87b3c2','#141e36',night);bottom=hexMix('#e6c692','#44505c',night)}else if(a.type==='colosseum'){top=hexMix('#91a9b5','#33243c',night);bottom=hexMix('#f1bd76','#8b5260',night)}else{top='#202b36';bottom='#3b4346'}
 const g=ctx.createLinearGradient(0,0,0,h*.86);g.addColorStop(0,top);g.addColorStop(.72,bottom);g.addColorStop(1,a.type==='beach'?'#bf8766':'#52454a');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
 const sunY=lerp(h*.16,h*.43,night),sx=w*(.73-.32*Math.cos(t*.012));if(a.type!=='industrial'&&a.type!=='dojo'){circle(sx,sunY,Math.min(w,h)*.048,night>.72?'#f4e8c1':'#ffdba0');if(night>.68){for(let i=0;i<34;i++){let x=((i*167+31)%w),y=((i*71+13)%(h*.42));if((i*3)%5<night*5)circle(x,y,1.1,'#fff5cf')}}}
